/*
 * WHO THIS PAGE IS ABOUT (TASK-L165 §5).
 *
 * The programme fixture says whose programme it is; the roster says who that
 * is. An explicit join on the learner id, never a match on a project's name.
 *
 * TWO NAME CHAINS, DELIBERATELY DIFFERENT, AND MERGING THEM IS THE DEFECT.
 * PORTED: displayName / audienceName -> LearnerShell.tsx.
 *
 *  - displayName = coachLabel ?? projectName ?? email ?? learnerId. The page's
 *    <h1>: any label that identifies the row is fine in a heading.
 *  - audienceName = coachLabel ?? email ?? "this learner". Wherever the page
 *    speaks ABOUT the person — here, the browser tab. It SKIPS projectName,
 *    because L128's audience control read "Shared with Bristol Community Garden
 *    Booking Site": a project named as though it were a person. The last
 *    fallback is words, never an id.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const fill = (t, v) => String(t || '').replace(/\{(\w+)\}/g, (m, k) => (k in v ? String(v[k]) : m));
if (Inputs.copy === undefined || Inputs.copy === null) return;
const W = ((plain(Inputs.copy) || {}).people || {}).learner;
if (!W) throw new Error('Pages/Learner: no people.learner copy');
const people = plain(Inputs.people);
const id = String(Inputs.learnerId || '');
if (!people || !id) return;
const person = people.find((p) => p.learnerId === id);
if (!person) throw new Error('Pages/Learner: the programme belongs to "' + id + '", who is not on the roster — the two fixtures disagree about who this is');
const or = (...xs) => xs.find((x) => x !== null && x !== undefined && x !== '');
const displayName = or(person.coachLabel, person.projectName, person.email, person.learnerId);
const audienceName = or(person.coachLabel, person.email) || W.thisLearner;
Outputs.person = person;
Outputs.programmes = person.programmes || [];
Outputs.displayName = displayName;
Outputs.audienceName = audienceName;
Outputs.meta = (person.email || W.noEmail) + (person.coachLabel && person.projectName ? ' · ' + person.projectName : '');
Outputs.tabTitle = fill(W.tabTitle, { name: audienceName });
Outputs.eyebrow = W.eyebrow;
Outputs.back = W.back;
Outputs.paceEyebrow = W.pace.eyebrow;
Outputs.trajectoryEyebrow = W.trajectory.eyebrow;

// The page title is the browser TAB. `Page.title` is read off the node's PARAMETERS at
// export time into the router index, and a connection to that port is silently ignored
// (TASK-L161 §1). So the parameter stays as the build-time fallback and the translated
// value overrides it here — the same node every page carries.
const t = Inputs.title;
if (typeof t === 'string' && t !== '' && typeof Noodl !== 'undefined' && Noodl.SEO) {
  Noodl.SEO.setTitle(t);
}

/*
 * A FRESH PAGE (TASK-L165). The surface, the open rows and the two pointers are
 * app variables — they have to be, because the rows that press them are inside
 * repeaters — and an app variable outlives the page. So arriving starts on
 * their programme with nothing open and nothing pointed at, exactly as a newly
 * mounted page does in the product. The SAVED filter is not touched: it is the
 * coach's preference and is meant to outlive the page (Logic/Feed filter).
 */
if (!Inputs.page) return;
Noodl.Variables.dbtCoachSurface = 'programme';
Noodl.Variables.dbtFeedOpen = [];
Noodl.Variables.dbtProgrammeOpened = [];
Noodl.Variables.dbtLogFocus = '';
Noodl.Variables.dbtProgrammeFocus = '';

/* Two surfaces, one showing. Anything that is not the log is the programme, so a
   page that has not been told yet opens on the programme — the reading a coach
   asked for first (L135). A Button paints its colours inline, so the tab that is
   on carries its colours as tokens rather than as a class. */
function plain(x) { return x && typeof x === 'object' && x.data ? x.data : x; }
if (Inputs.copy === undefined || Inputs.copy === null) return;
const W = ((plain(Inputs.copy) || {}).people || {}).learner;
if (!W) throw new Error('Pages/Learner: no people.learner copy');
const isLog = Inputs.surface === 'log';
const on = { bg: 'var(--primary)', fg: 'var(--primary-foreground)', border: 'var(--foreground)' };
const off = { bg: 'var(--surface-raised)', fg: 'var(--foreground)', border: 'var(--border-subtle)' };
const p = isLog ? off : on;
const l = isLog ? on : off;
Outputs.isProgramme = !isLog;
Outputs.isLog = isLog;
Outputs.programmeLabel = W.surface.programme;
Outputs.logLabel = W.surface.log;
Outputs.programmeBg = p.bg; Outputs.programmeFg = p.fg; Outputs.programmeBorder = p.border;
Outputs.logBg = l.bg; Outputs.logFg = l.fg; Outputs.logBorder = l.border;

/*
 * THE LOG POINTS AT THE PROGRAMME (TASK-L165 §4, L135 §3). The shell owns both
 * directions of "which row is being pointed at" (L138), and this is one of them.
 *
 * A pointed-at row OPENS by being handed `collapsed: false`. The kit row keys
 * its open state on its id AND that value, so a changed value re-derives it —
 * and nothing about the row's own component or the learner's page changes.
 * The set is STICKY: the row stays open after the pointer is handed back, and
 * if the coach folds it again that is their click, which the row keeps.
 *
 * The ORDER, the FOLD of every other row and the GROUPING are untouched. This
 * is not a re-fold for the coach — it is the one row the coach asked to see.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const rows = plain(Inputs.rows);
if (!rows) return;
const opened = new Set(plain(Inputs.opened) || []);
const focus = String(Inputs.focus || '');
if (focus) {
  const i = rows.findIndex((r) => r.id === focus);
  if (i !== -1 && !opened.has(focus)) {
    opened.add(focus);
    Noodl.Variables.dbtProgrammeOpened = Array.from(opened);
  }
  if (i !== -1) {
    /* By POSITION, because the thread holds this repeater and nothing else: a
       row's id is not in its DOM, and putting it there would change the
       learner's page (criterion 11). */
    Outputs.scrollSelector = '.dbt-coach-programme > :nth-child(' + (i + 1) + ')';
    Outputs.scroll();
  }
  Noodl.Variables.dbtProgrammeFocus = '';
}
Outputs.rows = rows.map((r) => (opened.has(r.id) && r.collapsed ? Object.assign({}, r, { collapsed: false }) : r));

/* A programme card asked to be shown in the log. The log is told WHICH row
   and the surface changes; Logic/Feed filter does the rest — clearing a
   filter that hides it, opening it — because it owns the log. */
const id = String(Inputs.id || '');
if (!id) return;
Noodl.Variables.dbtLogFocus = id;
Noodl.Variables.dbtCoachSurface = 'log';

/* A log row asked to be shown on the programme. The ROW's id is what the
   repeater hands back; what it POINTS AT is on the row (a signal points at its
   lesson, a note at what it is about), resolved once, by Logic/Ordered timeline. */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const id = String(Inputs.id || '');
const row = (plain(Inputs.rows) || []).find((r) => r.id === id);
if (!row || !row.canJump) return;
Noodl.Variables.dbtProgrammeFocus = row.jumpTo;
Noodl.Variables.dbtCoachSurface = 'programme';
